# Generated by a one-off converter (outside this repo). Edit by hand only after review.
EXAM = "CCAR-F"
EXAM_TITLE = "Claude Certified Architect - Foundations"
STUDY_GUIDE = "https://docs.anthropic.com/"
# Imported banks have one explanation per question and no per-choice rationale.
IMPORTED_SINGLE_EXPLANATION = True
RELAXED_STYLE = True
REF_PREFIXES = ('https://docs.anthropic.com/',)
CATEGORY = "Anthropic"
LEVEL = 1  # 1 entry/business, 2 associate, 3 expert
CONTENT_DATE = "2026-11"  # month the questions were last checked; the pages warn after six months

# Source: MichaelAanraad/CCAF d1.js to d5.js (150 questions; unofficial, community-reported domain weights), converted 2026-11-18.
DOMAINS = {
    "1": ("Agentic Architecture & Orchestration", "27%"),
    "2": ("Tool Design & MCP Integration", "18%"),
    "3": ("Claude Code Configuration & Workflows", "20%"),
    "4": ("Prompt Engineering & Structured Output", "20%"),
    "5": ("Context Management & Reliability", "15%"),
}
# group id: (title, questions per objective, objectives); OVERRIDE holds the real counts
GROUPS = {
    "1.1": ("Agentic Architecture & Orchestration", 0, [
        "Agentic Architecture & Orchestration",
    ]),
    "2.1": ("Tool Design & MCP Integration", 0, [
        "Tool Design & MCP Integration",
    ]),
    "3.1": ("Claude Code Configuration & Workflows", 0, [
        "Claude Code Configuration & Workflows",
    ]),
    "4.1": ("Prompt Engineering & Structured Output", 0, [
        "Prompt Engineering & Structured Output",
    ]),
    "5.1": ("Context Management & Reliability", 0, [
        "Context Management & Reliability",
    ]),
}
TOTAL = 150  # question bank size; validate.py and build.py check against it
OVERRIDE = {
    "1.1.1": 30,
    "2.1.1": 30,
    "3.1.1": 30,
    "4.1.1": 30,
    "5.1.1": 30,
}


def objectives():
    """{objective id: (text, target count)}"""
    out = {}
    for g, (_, n, objs) in GROUPS.items():
        for i, text in enumerate(objs, 1):
            oid = f"{g}.{i}"
            out[oid] = (text, OVERRIDE.get(oid, n))
    return out


if __name__ == "__main__":
    o = objectives()
    by_dom = {d: sum(n for k, (_, n) in o.items() if k[0] == d) for d in DOMAINS}
    print(len(o), "objectives,", sum(n for _, n in o.values()), "questions", by_dom)
    assert sum(n for _, n in o.values()) == TOTAL
    for g, (title, n, objs) in GROUPS.items():
        print(g, title, [o[f"{g}.{i}"][1] for i in range(1, len(objs) + 1)])
